@block QuadRotaryMonitor begin
    # Measurements of the quadruple pendulum (generated by design/build_models.py).
    #
    # Angles: phi_i, the absolute angle of link i from the upward vertical (deg), from the relative joint
    # angles; dev the largest |phi_i|.
    # Energy per link i from the bond graph's body i (RigidBody3D at the link's centre of mass): its twist
    # V = [w; v] (body frame, principal axes) and its pose g = [quaternion; position]:
    #   E_i = sum_k Jp_ik w_k^2/2 + m_i |v|^2/2 + m_i g0 (z - z_hang_i),
    # potential measured from the hanging rest, so the hanging chain has E = 0 and the upright chain at rest
    # E_up = sum m_i g0 2 (L_1 + .. + L_{i-1} + c_i). S_k = E_1 + .. + E_k is the stacked energy.
    # Ledger: E_tot = E_base + sum E_i, W_in = int u * sd dt (work of the actuator), W_loss = int (b_s sd^2 +
    # sum b_j wq_j^2) dt (base and joint friction); E_tot - W_in + W_loss stays constant up to the energy in
    # the stiff pivots.
    @inputs begin
        sd::Real, [unit = "rad/s"]
        u::Real, [unit = "N*m"]
        q1::Real, [unit = "rad"]
        q2::Real, [unit = "rad"]
        q3::Real, [unit = "rad"]
        q4::Real, [unit = "rad"]
        wq1::Real, [unit = "rad/s"]
        wq2::Real, [unit = "rad/s"]
        wq3::Real, [unit = "rad/s"]
        wq4::Real, [unit = "rad/s"]
        V1::Vec{6}
        V2::Vec{6}
        V3::Vec{6}
        V4::Vec{6}
        g1::Vec{7}
        g2::Vec{7}
        g3::Vec{7}
        g4::Vec{7}
    end
    @outputs begin
        th1::Real, [description = "Link 1 from the upward vertical (deg)"]
        th2::Real, [description = "Link 2 from the upward vertical (deg)"]
        th3::Real, [description = "Link 3 from the upward vertical (deg)"]
        th4::Real, [description = "Link 4 from the upward vertical (deg)"]
        dev::Real, [description = "Largest |angle| of the links from upright (deg)"]
        E1::Real, [unit = "J", description = "Energy of link 1 (kinetic + potential from hanging)"]
        E2::Real, [unit = "J", description = "Energy of link 2 (kinetic + potential from hanging)"]
        E3::Real, [unit = "J", description = "Energy of link 3 (kinetic + potential from hanging)"]
        E4::Real, [unit = "J", description = "Energy of link 4 (kinetic + potential from hanging)"]
        S1::Real, [unit = "J", description = "Stacked energy E_1 + .. + E_1"]
        S2::Real, [unit = "J", description = "Stacked energy E_1 + .. + E_2"]
        S3::Real, [unit = "J", description = "Stacked energy E_1 + .. + E_3"]
        S4::Real, [unit = "J", description = "Stacked energy E_1 + .. + E_4"]
        E_up::Real, [unit = "J", description = "UPRIGHT level: the chain upright at rest"]
        E_base::Real, [unit = "J", description = "Kinetic energy of the arm and hub"]
        E_tot::Real, [unit = "J", description = "Total mechanical energy"]
        W_in::Real, [unit = "J", description = "Work done by the actuator"]
        W_loss::Real, [unit = "J", description = "Energy dissipated by friction"]
        ledger::Real, [unit = "J", description = "E_tot - W_in + W_loss (constant)"]
    end
    @parameters begin
        m::Vec{4} = [0.03, 0.03, 0.03, 0.03], [unit = "kg", description = "Link masses"]
        Jp1::Vec{3} = [5.4e-07, 5.652e-05, 5.652e-05], [unit = "kg*m^2", description = "Principal inertias of link 1"]
        Jp2::Vec{3} = [5.4e-07, 5.652e-05, 5.652e-05], [unit = "kg*m^2", description = "Principal inertias of link 2"]
        Jp3::Vec{3} = [5.4e-07, 5.652e-05, 5.652e-05], [unit = "kg*m^2", description = "Principal inertias of link 3"]
        Jp4::Vec{3} = [5.4e-07, 5.652e-05, 5.652e-05], [unit = "kg*m^2", description = "Principal inertias of link 4"]
        h_hang::Vec{4} = [-0.075, -0.225, -0.375, -0.525], [unit = "m", description = "Height of each COM at the hanging rest"]
        J_axis::Real = 0.011004799999999999, [unit = "kg*m^2", description = "Arm and hub inertia about the vertical axis"]
        b_s::Real = 0.01, [description = "Base friction coefficient"]
        b_j::Real = 2e-05, [unit = "N*m*s/rad", description = "Joint friction coefficient"]
        g0::Real = 9.81, [unit = "m/s^2"]
    end
    @variables begin
        Win::Real = 0.0, [unit = "J"]
        Wloss::Real = 0.0, [unit = "J"]
    end
    @equations begin
        th1 ~ q1 * 57.29577951308232
        th2 ~ th1 + q2 * 57.29577951308232
        th3 ~ th2 + q3 * 57.29577951308232
        th4 ~ th3 + q4 * 57.29577951308232
        dev ~ max(max(abs(th1), abs(th2)), max(abs(th3), abs(th4)))
        E1 ~ 0.5 * (Jp1[1] * V1[1]^2 + Jp1[2] * V1[2]^2 + Jp1[3] * V1[3]^2) + 0.5 * m[1] * (V1[4]^2 + V1[5]^2 + V1[6]^2) + m[1] * g0 * (g1[7] - h_hang[1])
        E2 ~ 0.5 * (Jp2[1] * V2[1]^2 + Jp2[2] * V2[2]^2 + Jp2[3] * V2[3]^2) + 0.5 * m[2] * (V2[4]^2 + V2[5]^2 + V2[6]^2) + m[2] * g0 * (g2[7] - h_hang[2])
        E3 ~ 0.5 * (Jp3[1] * V3[1]^2 + Jp3[2] * V3[2]^2 + Jp3[3] * V3[3]^2) + 0.5 * m[3] * (V3[4]^2 + V3[5]^2 + V3[6]^2) + m[3] * g0 * (g3[7] - h_hang[3])
        E4 ~ 0.5 * (Jp4[1] * V4[1]^2 + Jp4[2] * V4[2]^2 + Jp4[3] * V4[3]^2) + 0.5 * m[4] * (V4[4]^2 + V4[5]^2 + V4[6]^2) + m[4] * g0 * (g4[7] - h_hang[4])
        S1 ~ E1
        S2 ~ S1 + E2
        S3 ~ S2 + E3
        S4 ~ S3 + E4
        E_up ~ m[1] * g0 * (-2.0 * h_hang[1]) + m[2] * g0 * (-2.0 * h_hang[2]) + m[3] * g0 * (-2.0 * h_hang[3]) + m[4] * g0 * (-2.0 * h_hang[4])
        E_base ~ 0.5 * J_axis * sd^2
        E_tot ~ E_base + S4
        ddt(Win) ~ u * sd
        ddt(Wloss) ~ b_s * sd^2 + b_j * (wq1^2 + wq2^2 + wq3^2 + wq4^2)
        W_in ~ Win
        W_loss ~ Wloss
        ledger ~ E_tot - Win + Wloss
    end
end
